            abandoned
                .write_page(&cx, p3, &vec![0x44; ps])
                .await
                .unwrap();
            abandoned.rollback(&cx).await.unwrap();

            let current_db_size = pager.published_snapshot().db_size;
            let mut txn = pager.begin(&cx, TransactionMode::Concurrent).await.unwrap();
