            txn1.commit(&cx).await.unwrap();

            // Overwrite and rollback.
            let mut txn2 = pager.begin(&cx, TransactionMode::Immediate).await.unwrap();
            txn2.write_page(&cx, p, &vec![0xBB; ps]).await.unwrap();
